insert into learn_questions (
  authoring_key, scope, kind, gate, level_slug, module_slug, prompt, scenario,
  explanation, topic_tag, difficulty, pair_key, position
) values (
  'c11', 'GATE', 'SINGLE', 'clinical',
  NULL, NULL, 'Which pediatric conditions represent medical indications for heart transplantation?',
  NULL, 'The AHA scientific statement makes restrictive cardiomyopathy an indication only where it is associated with reactive pulmonary hypertension — the qualifier carries the recommendation, so restrictive cardiomyopathy alone is not sufficient. Separately, infants with a functional single ventricle are candidates when specific anatomic findings are present: severe coronary artery stenosis or atresia, moderate-to-severe AV or semilunar valve disease, or severe ventricular dysfunction. Two commonly repeated answers do not survive the source: hypoplastic left heart syndrome is not itself a listed indication (improving staged Norwood palliation outcomes have decreased transplant as primary therapy for it), and severe Ebstein''s anomaly does not appear in the statement at all.', 'gate-clinical',
  1, NULL, 11
) on conflict (authoring_key) do update set
  scope = excluded.scope, kind = excluded.kind, gate = excluded.gate,
  level_slug = excluded.level_slug, module_slug = excluded.module_slug,
