insert into learn_questions (
  authoring_key, scope, kind, gate, level_slug, module_slug, prompt, scenario,
  explanation, topic_tag, difficulty, pair_key, position
) values (
  'c12', 'GATE', 'SINGLE', 'clinical',
  NULL, NULL, 'For a patient with COPD, which spirometric/clinical index criteria indicate lung transplantation?',
  NULL, 'The ISHLT consensus lists a COPD patient for transplant on any one of: a BODE index of 7 or more, an FEV1 below 15–20% predicted, three or more severe exacerbations in the preceding year, one severe exacerbation with acute hypercapnic respiratory failure, or moderate-to-severe pulmonary hypertension. Referral comes earlier, at BODE 5–6. A BODE of 7–10 is the top band of the original 0–10 score and carries roughly 80% mortality at four years, which is what makes it the listing threshold.', 'gate-clinical',
  1, NULL, 12
) on conflict (authoring_key) do update set
