) values (
  'c13', 'GATE', 'SINGLE', 'clinical',
  NULL, NULL, 'What rate of decline in Idiopathic Pulmonary Fibrosis (IPF) indicates lung transplant suitability?',
  NULL, 'The ISHLT consensus lists interstitial lung disease, including IPF, on any one of: a decline in FVC of 10% or more over six months of follow-up, a decline in DLCO of 15% or more over six months, desaturation below 88% or under 250 m on a six-minute-walk test (or a fall of more than 50 m over six months), pulmonary hypertension, or hospitalisation for respiratory decline, pneumothorax or acute exacerbation. Note the two figures differ: 10% for FVC, 15% for DLCO. A 5% FVC decline carries a poorer prognosis and may itself warrant listing.', 'gate-clinical',
  1, NULL, 13
) on conflict (authoring_key) do update set
