insert into learn_questions (
  authoring_key, scope, kind, gate, level_slug, module_slug, prompt, scenario,
  explanation, topic_tag, difficulty, pair_key, position
) values (
  'c14', 'GATE', 'SINGLE', 'clinical',
  NULL, NULL, 'What MELD score threshold indicates liver transplantation for decompensated cirrhosis?',
  NULL, 'Liver transplantation is indicated for decompensated cirrhosis or fulminant hepatic failure, and MELD 15 is the point where transplant starts to help rather than harm: below it, mortality after transplant was higher than for comparable candidates left on the waiting list. 📌 Source Note: the specific “≥15” cutoff comes from the United States OPTN “Share 15” allocation policy adopted on the strength of that finding — a geographic organ-sharing rule built on the US multi-region structure, not a universal clinical threshold. MELD itself is South African practice: SA allocates deceased-donor livers sickest-first by MELD on a single combined waiting list. What has no confirmed SA equivalent is the ≥15 regional-sharing figure.', 'gate-clinical',
  1, NULL, 14
) on conflict (authoring_key) do update set
  scope = excluded.scope, kind = excluded.kind, gate = excluded.gate,
