insert into learn_questions (
  authoring_key, scope, kind, gate, level_slug, module_slug, prompt, scenario,
  explanation, topic_tag, difficulty, pair_key, position
) values (
  'b1', 'GATE', 'SINGLE', 'basics',
  NULL, NULL, 'If a person becomes an organ donor, does their family have to pay for the donation surgery or procurement?',
  NULL, 'The Organ Donor Foundation states it plainly: the donor and their family incur no costs, because the hospital or tissue bank covers the medical expenses of the donation from the moment consent is given. Say it that way. No provision allocating those costs was found in the National Health Act or its regulations — section 60 prohibits trading in tissue, which is a different rule — so “the law says so” is a stronger claim than the sources support. The family still pays for the care given before death, as for any admission.', 'gate-basics',
  1, NULL, 1
) on conflict (authoring_key) do update set
  scope = excluded.scope, kind = excluded.kind, gate = excluded.gate,
  level_slug = excluded.level_slug, module_slug = excluded.module_slug,
  prompt = excluded.prompt, scenario = excluded.scenario,
  explanation = excluded.explanation, topic_tag = excluded.topic_tag,
  difficulty = excluded.difficulty, pair_key = excluded.pair_key,
  position = excluded.position, updated_at = now();

