insert into learn_questions (
  authoring_key, scope, kind, gate, level_slug, module_slug, prompt, scenario,
  explanation, topic_tag, difficulty, pair_key, position
) values (
  'b2', 'GATE', 'SINGLE', 'basics',
  NULL, NULL, 'Who must legally give final consent for organ donation to proceed in South Africa?',
  NULL, 'Section 62 puts the person first: a donation they made while alive — in a will, or before two competent witnesses — stands on its own. Only in its absence do relatives consent, and then in the order the Act sets: spouse, partner, major child, parent, guardian, major brother, major sister. “Major” means adult, and a partner ranks above every relative but a spouse. Written or witnessed telephonic consent is how coordinators document a relative’s decision in practice; that documentation requirement is professional practice rather than a provision of the Act.', 'gate-basics',
  1, NULL, 2
) on conflict (authoring_key) do update set
  scope = excluded.scope, kind = excluded.kind, gate = excluded.gate,
  level_slug = excluded.level_slug, module_slug = excluded.module_slug,
  prompt = excluded.prompt, scenario = excluded.scenario,
