) values (
  'QUESTION', 'c1', 'volunteer gate · clinical · question 1', 'According to South African guidelines, who is legally authorised to certify brain death?',
  'MEDICAL', 3, 'APPROVED',
  'National Health Act 61 of 2003 read directly, plus Regulation 9 of GN R180 of 2 March 2012 via Thomson & Labuschaigne, SAJBL 2024;17(1)', 'Keyed answer and explanation checked against: National Health Act 61 of 2003 read directly, plus Regulation 9 of GN R180 of 2 March 2012 via Thomson & Labuschaigne, SAJBL 2024;17(1)'
) on conflict (entity_type, entity_ref, claim) do update set
  location = excluded.location, category = excluded.category,
